def maxDiff(num):
    S = str(num)
    # Maximize by replacing first non-9 with 9 everywhere
    for ch in S:
        if ch != '9':
            max_num = int(S.replace(ch, '9'))
            break
    else:
        max_num = num
    # Minimize by replacing
    if S[0] != '1':
        min_num = int(S.replace(S[0], '1'))
    else:
        for ch in S[1:]:
            if ch not in ('0', S[0]):
                min_num = int(S.replace(ch, '0'))
                break
        else:
            min_num = num
    return max_num - min_num
